<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { productApi, type ProductDetailVO, type ProductListVO } from '@/api/product'
import { presaleApi, type PresaleActivity, type PresaleSku } from '@/api/presale'

const loading = ref(false); const saving = ref(false); const dialog = ref(false); const editingId = ref<number | null>(null)
const list = ref<PresaleActivity[]>([]); const products = ref<ProductListVO[]>([])
type ProductGroup = { productId: number | null; skus: PresaleSku[]; skuOptions: Array<{ id: number; specText?: string; price?: number; stock?: number }> }
const emptySku = (productId: number | null = null): PresaleSku => ({ productId, skuId: null, finalPrice: null, depositAmount: null, depositDeductionAmount: null, userLimit: 1, skuOptions: [] })
const emptyProductGroup = (): ProductGroup => ({ productId: null, skus: [emptySku()], skuOptions: [] })
const empty = (): PresaleActivity => ({ activityName: '', description: '', bannerImage: '', depositStartAt: '', depositEndAt: '', balanceStartAt: '', balanceEndAt: '', expectedShipAt: '', autoCloseExpired: 1, depositRefundRule: '尾款支付前可申请退还定金；商家未按期发货时全额退款。', merchantBreachRule: '商家未按预计时间发货时，用户可申请全额退款。', skus: [emptySku()] })
const form = ref<PresaleActivity>(empty())
const productGroups = ref<ProductGroup[]>([emptyProductGroup()])

async function load() { loading.value = true; try { const [page, productPage] = await Promise.all([presaleApi.page({ page: 1, size: 50 }), productApi.page({ page: 1, size: 200, status: 1, auditStatus: 1 })]); list.value = page?.list || []; products.value = productPage?.list || [] } finally { loading.value = false } }
function groupSkus(skus: PresaleSku[]) { const groups = new Map<number, ProductGroup>(); for (const item of skus) { const productId = Number(item.productId); if (!productId) continue; if (!groups.has(productId)) groups.set(productId, { productId, skus: [], skuOptions: [] }); groups.get(productId)!.skus.push({ ...item, skuOptions: [] }) }; return groups.size ? [...groups.values()] : [emptyProductGroup()] }
function openCreate() { editingId.value = null; form.value = empty(); productGroups.value = [emptyProductGroup()]; dialog.value = true }
async function openEdit(row: { id?: number }) { if (!row.id) return; const detail = await presaleApi.get(row.id); form.value = { ...detail, activityName: detail.name, skus: detail.skus || [] }; productGroups.value = groupSkus(detail.skus || []); await Promise.all(productGroups.value.map((group) => loadSkuOptions(group, false))); editingId.value = row.id; dialog.value = true }
async function loadSkuOptions(group: ProductGroup, reset = true) { if (!group.productId) { group.skuOptions = []; group.skus.forEach((item) => { item.productId = null; item.skuId = null; item.finalPrice = null; item.skuOptions = [] }); return }; const detail: ProductDetailVO = await productApi.get(Number(group.productId)); group.skuOptions = (detail.skus || []).map((sku) => ({ id: sku.id, specText: sku.specText, price: sku.price, stock: sku.stock })); group.skus.forEach((item) => { item.productId = group.productId; item.skuOptions = group.skuOptions; if (reset) { item.skuId = null; item.finalPrice = null } else syncBasePrice(item) }) }
function addProduct() { productGroups.value.push(emptyProductGroup()) }
function removeProduct(index: number) { if (productGroups.value.length > 1) productGroups.value.splice(index, 1) }
function canAddSku(group: ProductGroup) { if (!group.productId) return true; const selectedIds = new Set(group.skus.map((item) => Number(item.skuId)).filter(Boolean)); return selectedIds.size < group.skuOptions.length }
function addSku(group: ProductGroup) { if (!canAddSku(group)) return; const item = emptySku(group.productId); item.skuOptions = group.skuOptions; group.skus.push(item) }
function removeSku(group: ProductGroup, index: number) { if (group.skus.length > 1) group.skus.splice(index, 1) }
function productDisabled(productId: number, groupIndex: number) { return productGroups.value.some((group, index) => index !== groupIndex && Number(group.productId) === Number(productId)) }
function availableSkus(group: ProductGroup, item: PresaleSku) { const usedIds = new Set(group.skus.filter((other) => other !== item).map((other) => Number(other.skuId)).filter(Boolean)); return group.skuOptions.filter((sku) => !usedIds.has(Number(sku.id))) }
function selectedSku(item: PresaleSku) { return (item.skuOptions || []).find((sku) => sku.id === item.skuId) }
function syncBasePrice(item: PresaleSku) { const sku = selectedSku(item); item.finalPrice = sku?.price == null ? null : Number(sku.price) }
function flatSkus() { return productGroups.value.flatMap((group) => group.skus.map((item) => ({ ...item, productId: group.productId }))) }
function tailAmount(item: PresaleSku) { const finalPrice = Number(item.finalPrice || 0); const deduction = Number(item.depositDeductionAmount || 0); return finalPrice > deduction ? (finalPrice - deduction).toFixed(2) : '--' }
function validate() { const f = form.value; if (!f.activityName?.trim() || !f.depositStartAt || !f.depositEndAt || !f.balanceStartAt || !f.balanceEndAt || !f.expectedShipAt) return '请完整填写活动名称和时间'; if (!(new Date(f.depositStartAt) < new Date(f.depositEndAt) && new Date(f.depositEndAt) < new Date(f.balanceStartAt) && new Date(f.balanceStartAt) < new Date(f.balanceEndAt) && new Date(f.expectedShipAt) >= new Date(f.balanceEndAt))) return '时间顺序应为：定金开始 < 定金结束 < 尾款开始 < 尾款结束 ≤ 预计发货'; const requestSkus = flatSkus(); if (!requestSkus.length) return '至少配置一个主产品和 SKU'; const skuIds = new Set<number>(); for (const item of requestSkus) { const sku = selectedSku(item); const finalPrice = Number(item.finalPrice || 0); if (!item.productId || !item.skuId || !sku || skuIds.has(Number(item.skuId)) || !finalPrice || !item.depositAmount || !item.depositDeductionAmount || !item.userLimit) return skuIds.has(Number(item.skuId)) ? '同一活动不能重复绑定 SKU' : '请完整填写主产品、SKU、金额和限购'; skuIds.add(Number(item.skuId)); if (finalPrice <= Number(item.depositDeductionAmount)) return '商品最终价必须高于定金抵扣金额' }; return '' }
async function save() { const message = validate(); if (message) return ElMessage.warning(message); saving.value = true; try { const { id, name, status, statusText, phaseText, skus: ignoredSkus, ...activityFields } = form.value; const skus = flatSkus().map(({ id: skuId, skuOptions, productName, mainImage, specText, originalPrice, finalAmount, stock, depositCount, balanceSoldCount, balanceAmount, ...item }) => ({ ...item, finalPrice: Number(item.finalPrice) })); const payload = { ...activityFields, skus } as PresaleActivity; if (editingId.value) await presaleApi.update(editingId.value, payload); else await presaleApi.create(payload); ElMessage.success(editingId.value ? '预售活动已更新' : '预售活动已发布'); dialog.value = false; await load() } finally { saving.value = false } }
async function edit(row: { id?: number }) { try { await ElMessageBox.confirm('活动开始后核心规则不可修改，请确认当前活动尚未开始。', '编辑预售活动', { type: 'warning' }); await openEdit(row) } catch {} }
function time(row: { depositStartAt?: string; balanceEndAt?: string }) { return `${row.depositStartAt || '-'} 至 ${row.balanceEndAt || '-'}` }
onMounted(load)
</script>

<template>
  <div class="presale-page page">
    <div class="page-header"><div><span class="page-kicker">PRESALE DEPOSIT INFLATION</span><h1 class="page-title">预售定金膨胀</h1><p class="page-desc">先收定金锁定需求，尾款支付成功后才校验并扣减可发货库存，禁止与其他营销活动叠加。</p></div><div class="page-actions"><el-button @click="load">刷新</el-button><el-button type="primary" @click="openCreate">新建预售</el-button></div></div>
    <el-alert title="活动边界" description="定金只锁定需求，不占用库存；尾款逾期可自动关闭并退定金，也可进入待处理由商家人工处理。活动开始后核心规则锁定。" type="info" show-icon :closable="false" class="tip" />
    <el-table v-loading="loading" :data="list" class="activity-table"><el-table-column prop="name" label="活动名称" min-width="180" /><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="row.status === 1 ? 'success' : 'info'">{{ row.statusText }}</el-tag></template></el-table-column><el-table-column label="阶段" width="110"><template #default="{ row }">{{ row.phaseText }}</template></el-table-column><el-table-column label="时间" min-width="280"><template #default="{ row }">{{ time(row) }}</template></el-table-column><el-table-column label="SKU" width="80"><template #default="{ row }">{{ row.skus?.length || 0 }}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="primary" @click="row.id && presaleApi.stats(row.id).then((s) => ElMessage.info(`定金订单 ${s.depositOrderCount}，尾款支付 ${s.balancePaidOrderCount}，成交 ¥${s.finalAmount}`))">统计</el-button></template></el-table-column></el-table>
    <el-dialog v-model="dialog" :title="editingId ? '编辑预售活动' : '新建预售活动'" width="1040px" top="4vh"><el-form label-width="120px"><el-form-item label="活动名称"><el-input v-model="form.activityName" maxlength="128" placeholder="如：新品耳机预售" /></el-form-item><el-form-item label="活动说明"><el-input v-model="form.description" maxlength="500" placeholder="展示在小程序会场顶部" /></el-form-item><el-form-item label="定金时间"><el-date-picker v-model="form.depositStartAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="开始" /><span class="to">至</span><el-date-picker v-model="form.depositEndAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="结束" /></el-form-item><el-form-item label="尾款时间"><el-date-picker v-model="form.balanceStartAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="开始" /><span class="to">至</span><el-date-picker v-model="form.balanceEndAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="结束" /></el-form-item><el-form-item label="预计发货"><el-date-picker v-model="form.expectedShipAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" /></el-form-item><el-form-item label="逾期处理"><el-switch v-model="form.autoCloseExpired" :active-value="1" :inactive-value="0" active-text="自动关闭并退定金" inactive-text="进入待处理" /></el-form-item><el-form-item label="定金退款规则"><el-input v-model="form.depositRefundRule" type="textarea" :rows="2" /></el-form-item><el-form-item label="商家违约规则"><el-input v-model="form.merchantBreachRule" type="textarea" :rows="2" /></el-form-item><div v-for="(group, groupIndex) in productGroups" :key="groupIndex" class="product-editor"><div class="product-head"><strong>主产品 {{ groupIndex + 1 }}</strong><el-select v-model="group.productId" class="product-select" filterable placeholder="选择主产品" @change="loadSkuOptions(group)"><el-option v-for="product in products" :key="product.id" :label="product.name" :value="product.id" :disabled="productDisabled(product.id, groupIndex)" /></el-select><el-button v-if="productGroups.length > 1" link type="danger" @click="removeProduct(groupIndex)">移除主产品</el-button></div><div v-for="(item, index) in group.skus" :key="index" class="sku-row"><div class="sku-title">SKU {{ index + 1 }}</div><el-select v-model="item.skuId" class="sku-select" placeholder="选择 SKU 规格" :disabled="!group.skuOptions.length" @change="syncBasePrice(item)"><el-option v-for="sku in availableSkus(group, item)" :key="sku.id" :label="`${sku.specText || '默认规格'} · ¥${sku.price} · 库存${sku.stock}`" :value="sku.id" /></el-select><div class="number-field"><span>定金</span><el-input-number v-model="item.depositAmount" :min="0.01" :precision="2" controls-position="right" placeholder="定金金额" /></div><div class="number-field"><span>定金抵扣金额</span><el-input-number v-model="item.depositDeductionAmount" :min="0.01" :precision="2" controls-position="right" placeholder="抵扣金额" /></div><div class="number-field"><span>商品基础价</span><el-input-number v-model="item.finalPrice" :min="0.01" :precision="2" controls-position="right" placeholder="自动取 SKU 价格" disabled /></div><div class="number-field"><span>每人限购</span><el-input-number v-model="item.userLimit" :min="1" :max="999" :precision="0" controls-position="right" placeholder="限购数量" /></div><el-button v-if="group.skus.length > 1" link type="danger" class="remove-sku" @click="removeSku(group, index)">移除</el-button><div class="sku-hint">尾款 ¥{{ tailAmount(item) }} = 商品基础价 - 定金抵扣金额；实际总支付 ¥{{ item.finalPrice && item.depositAmount && Number(item.finalPrice) > Number(item.depositDeductionAmount || 0) ? (Number(item.depositAmount) + Number(item.finalPrice) - Number(item.depositDeductionAmount || 0)).toFixed(2) : '--' }}；不占用当前库存。</div></div><el-button v-if="canAddSku(group)" class="add-sku" @click="addSku(group)">+ 添加 SKU</el-button></div><el-button class="add-product" @click="addProduct">+ 添加主产品</el-button></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并发布</el-button></template></el-dialog>
  </div>
</template>

<style scoped>
.tip { margin-bottom: 18px; }.activity-table { border-radius: 16px; overflow: hidden; }.to { margin: 0 10px; color: var(--shop-muted); }.product-editor { margin: 18px 0; padding: 16px; border: 1px solid var(--shop-line); border-radius: 14px; background: #fffaf5; }.product-head { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; }.product-select { width: min(420px, 52%); }.sku-row { display: grid; grid-template-columns: 70px minmax(280px, 1.8fr) repeat(4, minmax(115px, 1fr)) 50px; gap: 10px; align-items: end; padding: 14px 0 10px; border-top: 1px solid rgba(218, 205, 192, .55); }.sku-title { padding-bottom: 10px; color: var(--shop-text); font-size: 13px; font-weight: 700; }.sku-select, .number-field :deep(.el-input-number) { width: 100%; }.number-field span { display: block; margin-bottom: 6px; color: var(--shop-muted); font-size: 12px; }.remove-sku { margin-bottom: 8px; }.sku-hint { grid-column: 2 / -1; color: var(--shop-muted); font-size: 12px; }.add-sku, .add-product { width: 100%; border-style: dashed; }.add-product { margin-top: 18px; }@media (max-width: 1100px) { .sku-row { grid-template-columns: 70px minmax(240px, 1.5fr) repeat(4, minmax(105px, 1fr)); }.remove-sku { grid-column: 1 / -1; justify-self: end; margin: 0; } }@media (max-width: 850px) { .product-head { flex-wrap: wrap; }.product-select { width: 100%; }.sku-row { grid-template-columns: 1fr 1fr; }.sku-title, .sku-select, .sku-hint { grid-column: 1 / -1; }.remove-sku { grid-column: auto; } }
</style>
